import json

BARS = [
    {"root":"A2","fifth":"E3","oct":"A3","pad":"A2"},
    {"root":"F2","fifth":"C3","oct":"F3","pad":"F2"},
    {"root":"C2","fifth":"G2","oct":"C3","pad":"C2"},
    {"root":"G2","fifth":"D3","oct":"G3","pad":"G2"},
]
ARP_NOTES = [
    ["A4","C5","E5","A5"],
    ["F4","A4","C5","F5"],
    ["C5","E5","G5","C6"],
    ["G4","B4","D5","G5"],
]
MELODY = [
    (0,"A4"),(2,"B4"),(4,"C5"),(6,"D5"),(8,"E5"),(10,"D5"),(12,"C5"),(14,"G4"),
    (16,"A4"),(18,"C5"),(20,"D5"),(22,"F5"),(24,"E5"),(26,"D5"),(28,"C5"),(30,"A4"),
    (32,"G4"),(34,"C5"),(36,"E5"),(38,"D5"),(40,"C5"),(42,"D5"),(44,"E5"),(46,"C5"),
    (48,"B4"),(50,"D5"),(52,"E5"),(54,"D5"),(56,"B4"),(58,"A4"),(60,"G4"),(62,"E4"),
]

LOUDNESS = {
    "intro":  {"kick":50,"snare":52,"hat":24,"hat_off":30,"shaker":0,"bass":38,"pad":28,"arp":0,"lead":0,"arp_intro":22},
    "verse":  {"kick":56,"snare":56,"hat":30,"hat_off":38,"shaker":26,"bass":46,"pad":36,"arp":30,"lead":50},
    "chorus": {"kick":60,"snare":60,"hat":34,"hat_off":42,"shaker":28,"bass":50,"pad":40,"arp":36,"lead":52},
}

def chorus_octave(note):
    import re
    m = re.match(r"([A-G]#?)(\d)", note)
    if not m: return note
    return f"{m.group(1)}{int(m.group(2))+1}"

def build_pattern(pat_id, kind):
    out = []
    L = LOUDNESS[kind]
    for bar in range(4):
        base = bar*16
        for r in (0,4,8,12):
            out.append((base+r, 0, "C2", 1, L["kick"]))
        for r in (4,12):
            out.append((base+r, 1, "C2", 2, L["snare"]))
        for r in range(0,16,2):
            vol = L["hat_off"] if r%4==2 else L["hat"]
            out.append((base+r, 2, "C2", 3, vol))
        if L["shaker"] > 0:
            for r in (3,7,11,15):
                out.append((base+r, 3, "C2", 4, L["shaker"]))
        b = BARS[bar]
        bass_seq = [b["root"], b["root"], b["fifth"], b["oct"], b["root"], b["fifth"], b["oct"], b["root"]]
        for i, nt in enumerate(bass_seq):
            out.append((base + i*2, 4, nt, 5, L["bass"]))
        out.append((base, 5, b["pad"], 8, L["pad"]))
        # arp
        if kind != "intro":
            tones = ARP_NOTES[bar]
            for r in range(16):
                out.append((base + r, 7, tones[r % 4], 6, L["arp"]))
        else:
            if bar >= 2:
                tones = ARP_NOTES[bar]
                for r in range(16):
                    out.append((base + r, 7, tones[r % 4], 6, L["arp_intro"]))
        # lead
        if kind != "intro":
            for (row, nt) in MELODY:
                if bar*16 <= row < bar*16+16:
                    note = nt
                    if kind == "chorus":
                        note = chorus_octave(nt)
                    out.append((row, 6, note, 7, L["lead"]))
    return out

def serialize(pat_id, kind):
    cells = build_pattern(pat_id, kind)
    calls = []
    for (row, chan, note, instr, vol) in cells:
        calls.append({"name":"pattern_set_cell","arguments":{
            "pattern":pat_id,"row":row,"channel":chan,"note":note,"instrument":instr,"volume":vol,"effect":0,"effect_param":0}})
    return calls

batch = []
batch.append({"name":"pattern_clear","arguments":{"pattern":0}})
batch.append({"name":"pattern_clear","arguments":{"pattern":1}})
batch.append({"name":"pattern_clear","arguments":{"pattern":2}})
for kind, idx in [("intro",0),("verse",1),("chorus",2)]:
    for c in serialize(idx, kind):
        batch.append(c)
batch.append({"name":"song_set","arguments":{"name":"KEYGEN TUNE","bpm":140,"speed":6,"length":3,"loop_start":0,"channels":8}})
batch.append({"name":"order_set","arguments":{"position":0,"pattern":0}})
batch.append({"name":"order_set","arguments":{"position":1,"pattern":1}})
batch.append({"name":"order_set","arguments":{"position":2,"pattern":2}})
with open("source/batch_compose.json","w") as f:
    json.dump(batch, f)
print("total cells:", sum(1 for c in batch if c["name"]=="pattern_set_cell"))
EOF
